import{_ as a,o as l,c as t,a0 as i}from"./chunks/framework.MyDJm6cd.js";const u=JSON.parse('{"title":"fleetd 公网中继角色（dev 机）设计","description":"","frontmatter":{},"headers":[],"relativePath":"relay-design.md","filePath":"relay-design.md"}'),d={name:"relay-design.md"};function o(n,e,r,s,h,f){return l(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="fleetd-公网中继角色-dev-机-设计" tabindex="-1">fleetd 公网中继角色（dev 机）设计 <a class="header-anchor" href="#fleetd-公网中继角色-dev-机-设计" aria-label="Permalink to &quot;fleetd 公网中继角色（dev 机）设计&quot;">​</a></h1><p>状态：设计定稿，待实现。日期：2026-11-26。 背景：舰队连通性 100% 依赖 ZeroTier；ZT 断线即全舰队失联。 用户令：公网角色放 dev（唯一公网机），舰主动出站连接，SSH 不作为依赖 （部分 Windows 不开 SSH）。</p><h2 id="角色定义" tabindex="-1">角色定义 <a class="header-anchor" href="#角色定义" aria-label="Permalink to &quot;角色定义&quot;">​</a></h2><p>dev 是 <strong>fleetd 公网接入点（Public Relay / Rendezvous）</strong>，不是第二个 flagship：</p><ol><li><strong>通道中继</strong>：flagship 与舰都只做出站连接到 dev；dev 把两边的流量对上号。</li><li><strong>保底路径</strong>：ZT 内网直连为主（快路径），dev 公网为备（慢路径）， 断线自动切换、恢复自动回内网。</li><li><strong>不做业务</strong>：dev 不存台账、不派单、不跑 job——台账永远只在 flagship。 dev 宕机的后果 = 退化回&quot;只有 ZT 在线时可用&quot;，不丢数据。</li></ol><h2 id="需要的功能清单-按实现顺序" tabindex="-1">需要的功能清单（按实现顺序） <a class="header-anchor" href="#需要的功能清单-按实现顺序" aria-label="Permalink to &quot;需要的功能清单（按实现顺序）&quot;">​</a></h2><h3 id="f1-flagship-公网暴露-dev-反代" tabindex="-1">F1. flagship 公网暴露（dev 反代） <a class="header-anchor" href="#f1-flagship-公网暴露-dev-反代" aria-label="Permalink to &quot;F1. flagship 公网暴露（dev 反代）&quot;">​</a></h3><ul><li>dev 上 nginx/caddy 反代 <code>https://dev.xxx/fleetd/</code> → <code>flagship:3790</code>（经 ZT 或内网）。</li><li>TLS 由 dev 终结；flagship 侧 fleetd 只监听（serve_on 已支持绑定地址）。</li><li>鉴权：共享 token（<code>FLEETD_RELAY_TOKEN</code>），agent 心跳/拉单必带，dev 只转发不解析。</li></ul><h3 id="f2-舰端-agent-模式-fleetd-agent-出站-only" tabindex="-1">F2. 舰端 agent 模式（fleetd agent，出站 only） <a class="header-anchor" href="#f2-舰端-agent-模式-fleetd-agent-出站-only" aria-label="Permalink to &quot;F2. 舰端 agent 模式（fleetd agent，出站 only）&quot;">​</a></h3><ul><li><code>fleetd agent --flagship &lt;url&gt; [--flagship &lt;url2&gt; ...] --name &lt;seat&gt; --workdir &lt;dir&gt;</code></li><li>多 flagship URL 按序试：主 ZT 内网 → 备 dev 公网；失败自动切换、恢复自动回主。</li><li>心跳（默认 30s）：POST <code>/v1/agent/heartbeat</code> 带 {seat, head, dirty, ver}。</li><li>断线重连：循环重试，失败仅记日志，进程不死。</li><li>任务下发：心跳响应内嵌待派任务（pull 模式）；执行完结果随下次心跳回执。</li><li>Windows 无 SSH 也成立：只要出站 HTTP 通就能被管。</li></ul><h3 id="f3-flagship-端-agent-接入点" tabindex="-1">F3. flagship 端 agent 接入点 <a class="header-anchor" href="#f3-flagship-端-agent-接入点" aria-label="Permalink to &quot;F3. flagship 端 agent 接入点&quot;">​</a></h3><ul><li><code>POST /v1/agent/heartbeat</code>：登记舰存活/状态（写 events 台账）+ 返回待派任务。</li><li>台账加 <code>agent_seen</code> 字段：区分&quot;SSH 可达&quot;与&quot;agent 心跳可达&quot;两种活性。</li><li>派单路由升级：优先 SSH push（在线且快），不可达且 agent 心跳活 → 排入 pull 队列，等舰下次心跳带走。</li></ul><h3 id="f4-dev-侧守护" tabindex="-1">F4. dev 侧守护 <a class="header-anchor" href="#f4-dev-侧守护" aria-label="Permalink to &quot;F4. dev 侧守护&quot;">​</a></h3><ul><li>反代配置落 systemd + cloudflare-tunnel-watchdog 同款看门狗（已有 skill）。</li><li>dev 只需 nginx + 一条 location 块；无 fleetd 组件、无状态。</li></ul><h3 id="f5-安全边界-用户安全默认-数据外发默认关" tabindex="-1">F5. 安全边界（用户安全默认：数据外发默认关） <a class="header-anchor" href="#f5-安全边界-用户安全默认-数据外发默认关" aria-label="Permalink to &quot;F5. 安全边界（用户安全默认：数据外发默认关）&quot;">​</a></h3><ul><li>心跳只带 seat/git 元数据，不带代码/日志正文；任务文本经 dev 中转属必要 最小面。</li><li>token 校验失败一律 403；dev 日志不落请求体。</li><li>后续可加：flagship↔舰 payload 端到端加密（dev 零知识），一期不做。</li></ul><h3 id="f6-可观测" tabindex="-1">F6. 可观测 <a class="header-anchor" href="#f6-可观测" aria-label="Permalink to &quot;F6. 可观测&quot;">​</a></h3><ul><li><code>fleetd status</code> 增列：每舰 <code>via: zt|relay|down</code>（当前走的路径）。</li><li>心跳超时 3 轮 → events 记 seat down；恢复自动记 up。</li></ul><h2 id="非目标-明确不做" tabindex="-1">非目标（明确不做） <a class="header-anchor" href="#非目标-明确不做" aria-label="Permalink to &quot;非目标（明确不做）&quot;">​</a></h2><ul><li>dev 不做第二 flagship（不持有台账、不决策）。</li><li>不做 P2P 打洞（WebRTC 等）——出站中继已满足需求，打洞复杂度不值。</li><li>不替换 SSH push 主路径——内网直连优先级永远最高。</li></ul><h2 id="验收口径" tabindex="-1">验收口径 <a class="header-anchor" href="#验收口径" aria-label="Permalink to &quot;验收口径&quot;">​</a></h2><ol><li>断 ZT（flagship 或任一舰）→ 该舰心跳自动经 dev 公网继续，<code>status</code> 显示 relay。</li><li>恢复 ZT → 自动切回内网，<code>status</code> 显示 zt。</li><li>Windows 舰关掉 SSH 服务 → 派单/巡检/任务回执全链路仍可用（纯 agent 模式）。</li><li>dev 宕机 → ZT 在线时无影响；ZT 也断时该舰标记 down（不丢台账数据）。</li></ol>',22)])])}const g=a(d,[["render",o]]);export{u as __pageData,g as default};
